steps.text:
//--- VIOC specops_player8: maximo de operaciones PEDIDAS en curso por jugador (lobby VIOC_SPECOPS_MAX_PLAYER, 8 por
//--- defecto), aparte del maximo de la IA por bando (VIOC_SO_MAXACTIVE).
VIOC_SO_MAXPLAYER = missionNamespace getVariable ["VIOC_SPECOPS_MAX_PLAYER", 8];
if !(VIOC_SO_MAXPLAYER isEqualType 0) then {VIOC_SO_MAXPLAYER = 8};
VIOC_SO_MAXPLAYER = ((round VIOC_SO_MAXPLAYER) max 1) min 20;

class VIOC_SPECOPS_MAX_PLAYER {
	title = "VIOC: Operaciones especiales pedidas por ti: maximo en curso a la vez (aparte del maximo de la IA)";
	values[] = {1,2,3,5,8,10};
	texts[] = {"1","2","3","5","8","10"};
	default = 8;
};
